    Etab, Role, User = apps.get_model("core", "Etablissement"), apps.get_model("accounts", "Role"), apps.get_model("accounts", "User")
    for e in Etab.objects.all():
        for r in ROLES:
            Role.objects.get_or_create(etablissement_id=e.pk, key=r, defaults={"label": ROLE_LABELS[r], "base": r, "perms": sorted(DEFAULT_PERMS.get(r, set())),
                                                                              "locked": r in LOCKED_ROLES, "builtin": True})
        for role in Role.objects.filter(etablissement_id=e.pk):
            User.objects.filter(etablissement_id=e.pk, role=role.key, role_ref__isnull=True).update(role_ref=role)


